-- Separate consent: event alerts never opt members into administrator announcements.
create table stroked_alerts.announcement_preferences(
 user_id uuid primary key references auth.users(id) on delete cascade,
 opted_in boolean not null default false,regions jsonb not null default '["PEI"]',categories jsonb not null default '["Motorcycles"]',
 consent_at timestamptz,updated_at timestamptz not null default now(),unsubscribe_token uuid not null unique default gen_random_uuid()
);
create table stroked_alerts.announcements(
 id uuid primary key default gen_random_uuid(),created_by uuid not null references auth.users(id),subject text not null,body text not null,
 regions jsonb not null,categories jsonb not null,status text not null default 'draft' check(status in ('draft','queued','cancelled')),
 created_at timestamptz not null default now(),queued_at timestamptz
);
alter table stroked_alerts.announcement_preferences enable row level security;
alter table stroked_alerts.announcements enable row level security;
revoke all on stroked_alerts.announcement_preferences,stroked_alerts.announcements from public,anon,authenticated;
alter table stroked_alerts.outbox add column announcement_id uuid references stroked_alerts.announcements(id);
create index stroked_announcement_jobs on stroked_alerts.outbox(announcement_id) where announcement_id is not null;
create function stroked_alerts.valid_announcement_choices(r jsonb,c jsonb) returns boolean language sql immutable set search_path='' as $$select case when jsonb_typeof(r) is distinct from 'array' or jsonb_typeof(c) is distinct from 'array' then false else jsonb_array_length(r)<=14 and jsonb_array_length(c)<=6 and not exists(select 1 from jsonb_array_elements_text(r) x where x is null or x not in ('All Canada','PEI','Nova Scotia','New Brunswick','Newfoundland and Labrador','Quebec','Ontario','Manitoba','Saskatchewan','Alberta','British Columbia','Yukon','Northwest Territories','Nunavut')) and not exists(select 1 from jsonb_array_elements_text(c) x where x is null or x not in ('Motorcycles','ATVs / Off-road','Classic cars','Cars & trucks','Snowmobiles','Motocross / Dirt track')) end$$;
create function stroked_alerts.announcement_matches(p stroked_alerts.announcement_preferences,a stroked_alerts.announcements) returns boolean language sql immutable set search_path='' as $$select (jsonb_array_length(a.regions)=0 or a.regions ? 'All Canada' or p.regions ? 'All Canada' or exists(select 1 from jsonb_array_elements_text(a.regions) x where p.regions ? x)) and (jsonb_array_length(a.categories)=0 or exists(select 1 from jsonb_array_elements_text(a.categories) x where p.categories ? x))$$;
create function stroked_alerts.announcement_recipients(a stroked_alerts.announcements) returns setof uuid language sql stable security definer set search_path='' as $$select p.user_id from stroked_alerts.announcement_preferences p join auth.users u on u.id=p.user_id where p.opted_in and u.email_confirmed_at is not null and u.deleted_at is null and coalesce(u.email,'')<>'' and not exists(select 1 from stroked_live_v55.member_blocks b where b.user_id=u.id) and stroked_alerts.announcement_matches(p,a)$$;
create function public.stroked_live_v55_my_announcement_settings() returns jsonb language plpgsql stable security definer set search_path='' as $$declare u uuid:=stroked_live_v55.verified_uid();begin return coalesce((select jsonb_build_object('opted_in',opted_in,'regions',regions,'categories',categories,'consent_at',consent_at) from stroked_alerts.announcement_preferences where user_id=u),'{"opted_in":false,"regions":["PEI"],"categories":["Motorcycles"]}'::jsonb);end$$;
create function public.stroked_live_v55_save_announcement_settings(p_settings jsonb) returns boolean language plpgsql security definer set search_path='' as $$declare u uuid:=stroked_live_v55.verified_uid();r jsonb:=p_settings->'regions';c jsonb:=p_settings->'categories';v boolean;begin
 if length(p_settings::text)>2000 or jsonb_typeof(p_settings->'opted_in') is distinct from 'boolean' or not stroked_alerts.valid_announcement_choices(r,c) then raise exception 'Choose valid announcement options';end if;
 v:=(p_settings->>'opted_in')::boolean;if v and (jsonb_array_length(r)=0 or jsonb_array_length(c)=0) then raise exception 'Choose a region and at least one category';end if;
 insert into stroked_alerts.announcement_preferences(user_id,opted_in,regions,categories,consent_at) values(u,v,r,c,case when v then now() end)
 on conflict(user_id) do update set opted_in=v,regions=r,categories=c,updated_at=now(),consent_at=case when v and not announcement_preferences.opted_in then now() else announcement_preferences.consent_at end,unsubscribe_token=case when v and not announcement_preferences.opted_in then gen_random_uuid() else announcement_preferences.unsubscribe_token end;
 return true;end$$;
-- The secret token only appears in that recipient's email; the endpoint reveals no account information.
create function public.stroked_unsubscribe_announcements(p_token uuid) returns boolean language plpgsql security definer set search_path='' as $$begin update stroked_alerts.announcement_preferences set opted_in=false,updated_at=now() where unsubscribe_token=p_token;return true;end$$;
create function public.stroked_live_v55_admin_prepare_announcement(p_subject text,p_body text,p_regions jsonb,p_categories jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=stroked_live_v55.verified_uid();a stroked_alerts.announcements%rowtype;n int;begin
 if not stroked_live_v55.is_admin() then raise exception 'Administrator only';end if;
 if length(trim(coalesce(p_subject,''))) not between 3 and 150 or p_subject ~ E'[\r\n]' or length(trim(coalesce(p_body,''))) not between 20 and 10000 or not stroked_alerts.valid_announcement_choices(p_regions,p_categories) then raise exception 'Use a subject of 3–150 characters, a message of 20–10000 characters, and valid audience choices';end if;
 if (select count(*) from stroked_alerts.announcements where created_by=u and created_at>now()-interval '1 hour')>=30 then raise exception 'Too many previews. Please try again later';end if;
 insert into stroked_alerts.announcements(created_by,subject,body,regions,categories) values(u,trim(p_subject),trim(p_body),p_regions,p_categories) returning * into a;
 select count(*) into n from stroked_alerts.announcement_recipients(a);return jsonb_build_object('id',a.id,'recipient_count',n,'subject',a.subject,'body',a.body);end$$;
create function public.stroked_live_v55_admin_send_announcement(p_id uuid,p_test boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=stroked_live_v55.verified_uid();a stroked_alerts.announcements%rowtype;n int;begin
 if not stroked_live_v55.is_admin() then raise exception 'Administrator only';end if;
 if p_test is null then raise exception 'Choose a valid send option';end if;
 select * into a from stroked_alerts.announcements where id=p_id and created_by=u for update;if not found or a.status='cancelled' then raise exception 'Announcement is unavailable';end if;
 if p_test then
 insert into stroked_alerts.outbox(user_id,kind,payload,dedupe_key,announcement_id) values(u,'announcement_test',jsonb_build_object('subject',a.subject,'body',a.body),'announcement-test:'||a.id,a.id) on conflict(user_id,dedupe_key) where dedupe_key is not null do nothing;
 else
 if a.status='draft' then
 select count(*) into n from stroked_alerts.announcement_recipients(a);if n=0 then raise exception 'No subscribed members match this audience';end if;
 update stroked_alerts.announcements set status='queued',queued_at=now() where id=a.id;
 insert into stroked_alerts.outbox(user_id,kind,payload,dedupe_key,announcement_id) select recipient,'announcement',jsonb_build_object('subject',a.subject,'body',a.body),'announcement:'||a.id,a.id from stroked_alerts.announcement_recipients(a) recipient on conflict(user_id,dedupe_key) where dedupe_key is not null do nothing;
 end if;end if;
 select count(*) into n from stroked_alerts.outbox where announcement_id=a.id and kind=case when p_test then 'announcement_test' else 'announcement' end;return jsonb_build_object('queued',n,'test',p_test);end$$;
create function public.stroked_live_v55_admin_announcement_history() returns setof jsonb language plpgsql stable security definer set search_path='' as $$declare u uuid:=stroked_live_v55.verified_uid();begin if not stroked_live_v55.is_admin() then raise exception 'Administrator only';end if;return query select jsonb_build_object('id',a.id,'subject',a.subject,'status',a.status,'created_at',a.created_at,'queued',count(o.id) filter(where o.kind='announcement' and o.status in ('pending','processing')),'sent',count(o.id) filter(where o.kind='announcement' and o.status='sent'),'failed',count(o.id) filter(where o.kind='announcement' and o.status='failed'),'cancelled',count(o.id) filter(where o.kind='announcement' and o.status='cancelled'),'test_sent',count(o.id) filter(where o.kind='announcement_test' and o.status='sent')) from (select * from stroked_alerts.announcements order by created_at desc limit 20) a left join stroked_alerts.outbox o on o.announcement_id=a.id group by a.id,a.subject,a.status,a.created_at order by a.created_at desc;end$$;
create function public.stroked_live_v55_admin_cancel_announcement(p_id uuid) returns boolean language plpgsql security definer set search_path='' as $$declare u uuid:=stroked_live_v55.verified_uid();begin if not stroked_live_v55.is_admin() then raise exception 'Administrator only';end if;update stroked_alerts.announcements set status='cancelled' where id=p_id;update stroked_alerts.outbox set status='cancelled' where announcement_id=p_id and status in ('pending','processing');return true;end$$;
alter function stroked_alerts.eligible(stroked_alerts.outbox) rename to eligible_before_announcements;
create function stroked_alerts.eligible(o stroked_alerts.outbox) returns boolean language sql stable security definer set search_path='' as $$select case when o.kind in ('announcement','announcement_test') then exists(select 1 from auth.users u join stroked_alerts.announcements a on a.id=o.announcement_id where u.id=o.user_id and u.email_confirmed_at is not null and u.deleted_at is null and not exists(select 1 from stroked_live_v55.member_blocks b where b.user_id=u.id) and a.status<>'cancelled' and case when o.kind='announcement_test' then u.id=a.created_by and exists(select 1 from public.event_admins where user_id=u.id) else a.status='queued' and exists(select 1 from stroked_alerts.announcement_preferences p where p.user_id=u.id and p.opted_in and p.consent_at<=o.created_at and stroked_alerts.announcement_matches(p,a)) end) else stroked_alerts.eligible_before_announcements(o) end$$;
create function public.stroked_alert_announcement_can_send(p_id uuid) returns boolean language plpgsql security definer set search_path='' as $$declare o stroked_alerts.outbox%rowtype;begin select * into o from stroked_alerts.outbox where id=p_id;if not found or o.status<>'processing' then return false;end if;if not stroked_alerts.eligible(o) then update stroked_alerts.outbox set status='cancelled' where id=p_id;return false;end if;return true;end$$;

create or replace function public.stroked_alert_worker_claim() returns setof jsonb language plpgsql security definer set search_path='' as $$begin
 perform stroked_alerts.enqueue_reminders();
 update stroked_alerts.outbox o set status='cancelled' where status in ('pending','processing') and not stroked_alerts.eligible(o);
 return query with candidates as(select id from stroked_alerts.outbox where status in ('pending','processing') and available_at<=now() and attempts<5 and created_at>now()-interval '20 hours' order by created_at for update skip locked limit 10),claimed as(update stroked_alerts.outbox o set status='processing',attempts=attempts+1,available_at=now()+interval '5 minutes' from candidates c where c.id=o.id returning o.*) select jsonb_build_object('id',o.id,'event_id',o.event_id,'kind',o.kind,'payload',o.payload,'email',u.email,'unsubscribe_token',case when o.kind='announcement' then (select p.unsubscribe_token from stroked_alerts.announcement_preferences p where p.user_id=o.user_id) end) from claimed o join auth.users u on u.id=o.user_id where u.email_confirmed_at is not null;
 update stroked_alerts.outbox set status='failed',last_error='Retry window ended' where status in ('pending','processing') and (attempts>=5 or created_at<=now()-interval '20 hours') and available_at<=now();end$$;

revoke all on all functions in schema stroked_alerts from public,anon,authenticated;
revoke all on function public.stroked_live_v55_my_announcement_settings(),public.stroked_live_v55_save_announcement_settings(jsonb),public.stroked_live_v55_admin_prepare_announcement(text,text,jsonb,jsonb),public.stroked_live_v55_admin_send_announcement(uuid,boolean),public.stroked_live_v55_admin_announcement_history(),public.stroked_live_v55_admin_cancel_announcement(uuid),public.stroked_unsubscribe_announcements(uuid),public.stroked_alert_announcement_can_send(uuid) from public,anon,authenticated;
grant execute on function public.stroked_live_v55_my_announcement_settings(),public.stroked_live_v55_save_announcement_settings(jsonb),public.stroked_live_v55_admin_prepare_announcement(text,text,jsonb,jsonb),public.stroked_live_v55_admin_send_announcement(uuid,boolean),public.stroked_live_v55_admin_announcement_history(),public.stroked_live_v55_admin_cancel_announcement(uuid) to authenticated;
grant execute on function public.stroked_unsubscribe_announcements(uuid) to anon,authenticated;
grant execute on function public.stroked_alert_announcement_can_send(uuid) to service_role;
notify pgrst,'reload schema';
